export function apiKeyId(raw: string): ApiKeyId;        // validates non-empty and max length

export interface RatePolicy {
  readonly limit: number;       // > 0 integer
  readonly windowMs: number;    // > 0 integer
}

export type Decision =
  | { allowed: true;  remaining: number; resetAfterMs: number }
  | { allowed: false; retryAfterMs: number; resetAfterMs: number };

export interface RateLimiter {
  /** Atomically records one request for `key` and returns the verdict.
   *  Never throws: store failures resolve per `onStoreError`. */
