 *  Allowed requests increment curr. Keys expire after 2 * windowMs. */
declare const SLIDING_WINDOW_LUA: string;

/** Parse the raw Lua reply [allowed, remaining, retryAfterMs, resetAfterMs] into a domain type. */
function parseReply(raw: unknown): RateLimitDecision;   // throws on malformed reply

function windowKey(prefix: string, key: ApiKeyId): string;
```

