export type ApiKeyId = string & { readonly __brand: "ApiKeyId" };
export function apiKeyId(raw: string): ApiKeyId;  // validates: non-empty, bounded length

export type RateLimit = Readonly<{ requests: number; windowSeconds: number }>;

export type Decision =
  | { allowed: true;  remaining: number; degraded: boolean }   // degraded = store failed, failed open
  | { allowed: false; retryAfterMs: number };

export interface RateLimiter {
  /** Atomically records one request and decides. Never throws; store errors become a Decision per policy. */
  check(key: ApiKeyId): Promise<Decision>;
}

export type RateLimiterConfig = Readonly<{
  redis: RedisScriptRunner;          // narrow port, see below
  limit: RateLimit;
  onStoreError: "fail-open" | "fail-closed";
  keyPrefix?: string;                // default "rl"
  storeTimeoutMs?: number;           // default 50
}>;

export function createRateLimiter(config: RateLimiterConfig): RateLimiter;

export function rateLimitMiddleware(
  limiter: RateLimiter,
  opts: { keyOf: (req: Request) => string | undefined },  // missing key -> 401 upstream, not our concern
