// rate-limit/store.ts: private to the module

/** Narrow port so ioredis/node-redis stay out of the public types. */
export interface RedisScriptRunner {
  evalSha(sha: string, keys: string[], args: string[]): Promise<unknown>;
  scriptLoad(src: string): Promise<string>;
}

/** Raw reply from the Lua script, parsed immediately into a Decision. */
function parseReply(raw: unknown, limit: RateLimit): Decision;   // validates shape; throws on garbage
function bucketKeys(prefix: string, key: ApiKeyId, nowWindow: number): [cur: string, prev: string];
