```tsx
// src/Launch.tsx
import {AbsoluteFill, Sequence, interpolate, Easing, useCurrentFrame} from 'remotion';

const ACCENT = '#6EE7B7';
const BG = '#0B0F14';
const FG = '#E6EDF3';
const FPS = 30;
const s = (sec: number) => Math.round(sec * FPS);

const Fade: React.FC<{children: React.ReactNode}> = ({children}) => {
  const f = useCurrentFrame();
  const opacity = interpolate(f, [0, 10], [0, 1], {extrapolateRight: 'clamp'});
  const y = interpolate(f, [0, 10], [20, 0], {extrapolateRight: 'clamp'});
  return <div style={{opacity, transform: `translateY(${y}px)`}}>{children}</div>;
};

const Center: React.FC<{children: React.ReactNode}> = ({children}) => (
  <AbsoluteFill style={{background: BG, color: FG, justifyContent: 'center', alignItems: 'center', fontFamily: 'Inter, system-ui, sans-serif'}}>
    {children}
  </AbsoluteFill>
);

const Big: React.FC<{text: string; color?: string; size?: number}> = ({text, color = FG, size = 120}) => (
  <Center><Fade><div style={{fontSize: size, fontWeight: 700, color}}>{text}</div></Fade></Center>
);

const Terminal = () => {
  const f = useCurrentFrame();
  const cmd = 'DROP TABLE users;';
  const shown = cmd.slice(0, Math.floor(interpolate(f, [10, 70], [0, cmd.length], {extrapolateRight: 'clamp', extrapolateLeft: 'clamp'})));
  return (
    <Center>
      <div style={{fontFamily: 'monospace', fontSize: 64}}>
        <span style={{color: ACCENT}}>db=&gt; </span>{shown}
        <span style={{opacity: Math.floor(f / 15) % 2}}>▌</span>
      </div>
    </Center>
  );
};

const Timeline = () => {
  const f = useCurrentFrame();
  const total = 7 * 24 * 60; // minutes in 7 days
  // playhead scrubs from "now" back to a point ~2d 3h 14m ago, then settles
  const target = 2 * 24 * 60 + 3 * 60 + 14;
  const minutesBack = interpolate(f, [30, s(8)], [0, target], {
    easing: Easing.inOut(Easing.cubic), extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  });
  const x = interpolate(minutesBack, [0, total], [1, 0]); // 1 = right edge (now)
  const d = Math.floor(minutesBack / 1440);
  const h = Math.floor((minutesBack % 1440) / 60);
  const m = Math.floor(minutesBack % 60);
  const done = f > s(8) + 10;
  const W = 1500;

  return (
    <Center>
      <div style={{width: W, position: 'relative'}}>
        <div style={{fontSize: 56, marginBottom: 60, textAlign: 'center'}}>
          {d}d {h}h {m}m ago
        </div>
        <div style={{height: 12, background: '#1E2630', borderRadius: 6, position: 'relative'}}>
          {Array.from({length: 8}).map((_, i) => (
            <div key={i} style={{position: 'absolute', left: (i / 7) * W - 1, top: -14, width: 2, height: 40, background: '#334155'}} />
          ))}
          <div style={{position: 'absolute', left: 0, width: x * W, height: 12, background: ACCENT, borderRadius: 6, opacity: 0.35}} />
          <div style={{position: 'absolute', left: x * W - 14, top: -16, width: 28, height: 44, background: ACCENT, borderRadius: 8}} />
        </div>
        <div style={{display: 'flex', justifyContent: 'space-between', marginTop: 40, color: '#7D8590', fontSize: 28}}>
          <span>7 days ago</span><span>Now</span>
        </div>
        <div style={{marginTop: 80, textAlign: 'center'}}>
          <span style={{
            padding: '20px 48px', fontSize: 40, fontWeight: 600, borderRadius: 12,
            background: done ? ACCENT : '#1E2630', color: done ? BG : FG,
          }}>
            {done ? '✓ Restored' : 'Restore'}
          </span>
        </div>
      </div>
    </Center>
  );
};

const Callouts = () => {
  const items = ['Any minute.', '7 days back.', 'Built in.'];
  return (
    <Center>
      <div style={{fontSize: 96, fontWeight: 700}}>
        {items.map((t, i) => (
          <Sequence key={t} from={i * s(1.8)} layout="none">
            <Fade><div style={{color: i === 2 ? ACCENT : FG}}>{t}</div></Fade>
          </Sequence>
        ))}
      </div>
    </Center>
  );
};

export const Launch: React.FC = () => (
  <AbsoluteFill style={{background: BG}}>
    <Sequence from={0} durationInFrames={s(5)}><Terminal /></Sequence>
    <Sequence from={s(5)} durationInFrames={s(7)}><Big text="Now what?" color="#F87171" /></Sequence>
    <Sequence from={s(12)} durationInFrames={s(8)}><Big text="Snapshots" color={ACCENT} size={180} /></Sequence>
    <Sequence from={s(20)} durationInFrames={s(15)}><Timeline /></Sequence>
    <Sequence from={s(35)} durationInFrames={s(6)}><Callouts /></Sequence>
    <Sequence from={s(41)} durationInFrames={s(4)}><Big text="Snapshots are live." size={100} /></Sequence>
  </AbsoluteFill>
);
```

